rows=[]
for x in xs:
 s=Path(x['proposal']).read_text(); t=s
 if x['id'] in changes:
  old,new,deps,why=changes[x['id']];assert s.count(old)==1,(x['id'],s.count(old));t=s.replace(old,new)
